const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  throw new Error('DATABASE_URL is not set');
}

export default defineConfig({
  schema: 'prisma/schema',
  migrations: {
    path: 'prisma/migrations',
    seed: 'npx ts-node prisma/seeds/index.ts',
  },
  datasource: {
    url: DATABASE_URL,
  },
});
